import java.sql.*;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import vvv.model.Passageiro;
import vvv.model.DAOs.PassageiroDAO;

// Technical control authored for the pilot. Not generated by an agent or a human gold standard.
public class VvvUniquenessProbe {
    static Connection connection;
    static PassageiroDAO dao;
    static List<String> results = new ArrayList<>();
    static int failures;
    static Passageiro passenger(String email, String cpf) {
        return new Passageiro("Pessoa sintetica", email, cpf, "11999999999", LocalDate.of(1990, 1, 1));
    }
    static long count() throws SQLException {
        try (Statement s=connection.createStatement(); ResultSet r=s.executeQuery("SELECT count(*) FROM passageiro")) {r.next();return r.getLong(1);}
    }
    static void seed() throws SQLException {
        try (Statement s=connection.createStatement()) {s.execute("TRUNCATE TABLE passageiro RESTART IDENTITY");}
        if (!dao.salvar(passenger("primeiro@example.test", "11111111111"))) throw new SQLException("Fixture nao foi criada");
    }
    static void check(String name, boolean returned, boolean expected, long expectedRows) throws SQLException {
        long rows=count(); boolean passed=returned==expected && rows==expectedRows;
        if(!passed)failures++;
        results.add("{\"name\":\""+name+"\",\"status\":\""+(passed?"passed":"failed")+"\",\"returned\":"+returned+",\"expected_return\":"+expected+",\"rows\":"+rows+",\"expected_rows\":"+expectedRows+"}");
    }
    static Passageiro second() throws SQLException {
        if(!dao.salvar(passenger("segundo@example.test","22222222222")))throw new SQLException("Segunda fixture nao foi criada");
        try(Statement s=connection.createStatement(); ResultSet r=s.executeQuery("SELECT id FROM passageiro WHERE cpf='22222222222'")) {
            if(!r.next())throw new SQLException("Fixture ausente");
            Passageiro p=passenger("segundo@example.test","22222222222");p.setId(r.getLong(1));return p;
        }
    }
    public static void main(String[] args) throws Exception {
        // Literal disposable endpoint; never consult project credentials/default constructors.
        try(Connection c=DriverManager.getConnection("jdbc:postgresql://127.0.0.1:5432/tcc_test_vvv","postgres","")) {
            connection=c;dao=new PassageiroDAO(c);
            seed();check("cadastro_sem_duplicidade",dao.salvar(passenger("segundo@example.test","22222222222")),true,2);
            seed();check("cpf_duplicado",dao.salvar(passenger("segundo@example.test","11111111111")),false,1);
            seed();check("email_duplicado",dao.salvar(passenger("primeiro@example.test","22222222222")),false,1);
            seed();Passageiro p=second();p.setCpf("11111111111");check("edicao_cpf_duplicado",dao.editar(p),false,2);
            seed();p=second();p.setEmail("primeiro@example.test");check("edicao_email_duplicado",dao.editar(p),false,2);
            System.out.println("{\"kind\":\"technical-control/not-agent-generated\",\"tests\":["+String.join(",",results)+"],\"failures\":"+failures+"}");
        }
        if(failures>0)System.exit(2);
    }
}
